    summary:
      '**A lightweight lithium battery can make an electric wheelchair easier to fold, lift, and sell, but it also changes the shipping conversation.** Battery chemistry, watt-hour rating, packaging, labels, test documents, and carrier rules all affect whether an order moves smoothly from factory to distributor. For B2B buyers, a compliant battery file is part of the product specification — not paperwork to request after the container is booked.',
    tags: ['Lithium Battery', 'Shipping', 'Compliance'],
