    content: `
## Why Factory Audits Matter for Electric Wheelchair Sourcing

China produces over 60% of the world electric wheelchairs, with hundreds of factories ranging from world-class ISO-certified facilities to small workshops with inconsistent quality. For B2B importers, the difference between these suppliers can mean the difference between a successful product launch and a costly recall.

This guide provides a systematic due diligence framework specifically for electric wheelchair factory evaluation.

### Phase 1: Pre-Visit Research

#### 1. Verify Business Credentials

Before booking a flight, verify the basics:

| Document | What to Check |
| Business License | Company name matches your contact, valid dates, registered capital |
| Export License | Confirms legal export status |
| Tax Registration | Verifies the company operates legitimately |
| Bank Account | Company name matches the bank account for payments |

**Red flags:**
- Company name on Alibaba differs from business license
- Registered capital under 1 million RMB
- Business license issued less than 2 years ago

#### 2. Certificate Verification

Electric wheelchair manufacturers should hold:
- **ISO 13485** — Medical device quality management
- **CE Certificate (MDR)** — European market access with valid Notified Body number
- **FDA Registration** — US market access, verify via FDA website
- **UN38.3** — Lithium battery transport safety
- **Patent Certificates** — Confirms IP ownership for frame designs

#### 3. Export History Check

Ask for customs declarations, bills of lading, container loading photos, and customer references. A factory that cannot provide recent export documentation likely has limited export experience.

### Phase 2: On-Site Factory Audit

#### 4. Facility Assessment

| Area | What to Look For |
| Production floor size | At least 2,000-5,000 sqm |
| Cleanliness | Organized workspaces, clean floors |
| Safety equipment | Fire extinguishers, emergency exits |
| Lighting | Bright and consistent for inspection areas |
| Inventory | Raw materials in stock, WIP on line |

**The bathroom test:** A clean facility means clean production standards.

#### 5. Production Capability

Critical equipment to verify:
- Die-casting machines for one-piece frame production
- Welding stations for frame assembly
- Assembly line with organized workflow
- Painting/coating line for corrosion resistance
- Battery assembly area with safety protocols
- Testing equipment for load, range, and speed tests

#### 6. Quality Control Systems

| Stage | Inspection Point |
| Raw materials | Frame certification, motor specs, battery cell testing |
| In-process | Weld quality, alignment, wiring integrity |
| Final QC | Load test, range test, brake test |
| Pre-shipment | Cosmetic inspection, packaging quality |

#### 7. R&D Capability

Check for in-house engineering team, patent portfolio, and OEM/ODM customization capability.

### Phase 3: Commercial Due Diligence

#### 8. Pricing Analysis

For a magnesium alloy folding wheelchair at 42-50 KG with dual motors and LiFePO4 battery, expect FOB prices in the $1,800-$2,000 range. If a price seems too low, something is being compromised.

#### 9. Payment Terms

Industry standard: 30% deposit, 70% before shipment. Letter of Credit available for larger orders. Factories demanding 50%+ deposit without a track record are a red flag.

#### 10. After-Sales Support

Clarify: warranty period (1-2 years standard), warranty coverage, spare parts availability, technical support, return policy.

### Phase 4: Final Verification

#### 11. Sample Evaluation

Always order samples before volume commitment. Test range, load, fold mechanism. Verify specifications match.

#### 12. Third-Party Inspection

Consider SGS or Bureau Veritas for first orders. $500-$1,500 per inspection can prevent costly mistakes.

### How MiniElephant Measures Up

| Criteria | MiniElephant | Industry |
| Certifications | ISO 13485, CE, FDA | Often only CE |
| Frame | Integrated die-cast in-house | Often outsourced welding |
| R&D | In-house engineering + patents | Limited or outsourced |
| QC | 4-stage from raw material to pre-shipment | Typically 1-2 stages |
| Export | 50+ countries with documentation | Varies widely |
| Pricing | $1,850-$1,990 transparent | Often hidden costs |

> **Contact MiniElephant for a factory tour:** [www.semwheelchair.com/contact](https://www.semwheelchair.com/contact)
> **Browse our product line:** [www.semwheelchair.com/products](https://www.semwheelchair.com/products)
`,
