      'Air travel is one of the strongest growth drivers for lightweight folding electric wheelchairs — and one of the most misunderstood specifications in the catalog. This guide covers airline lithium battery rules, the wheelchair specifications that clear check-in, and what importers should verify to serve the travel mobility segment.',
